package dev.aether.api.security;
import org.springframework.beans.factory.annotation.Value;import org.springframework.boot.ApplicationArguments;import org.springframework.boot.ApplicationRunner;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Component;import org.springframework.transaction.annotation.Transactional;import java.util.Set;
@Component public class AdminBootstrap implements ApplicationRunner {private final String email;private final String password;private final AccountUserRepository users;private final AccountRoleRepository roles;private final PasswordEncoder encoder;public AdminBootstrap(@Value("${ADMIN_BOOTSTRAP_EMAIL:}")String email,@Value("${ADMIN_BOOTSTRAP_PASSWORD:}")String password,AccountUserRepository users,AccountRoleRepository roles,PasswordEncoder encoder){this.email=email;this.password=password;this.users=users;this.roles=roles;this.encoder=encoder;}@Override @Transactional public void run(ApplicationArguments args){if(email.isBlank()&&password.isBlank())return;if(email.isBlank()||password.length()<14)throw new IllegalStateException("Set both ADMIN_BOOTSTRAP_EMAIL and ADMIN_BOOTSTRAP_PASSWORD (minimum 14 characters) or leave both empty.");if(users.findByEmailIgnoreCase(email).isPresent())return;users.save(new AccountUser(email.trim().toLowerCase(),encoder.encode(password),Set.of(roles.findByName("SUPER_ADMIN").orElseThrow())));}}
